class ChordWait:
    """The wait of a talk key that also types. press() starts it, other() ends it as typing, and release() ends it as
    a tap. When the wait passes with the key still down, held(device, code, pressed_at) runs."""

    def __init__(self, loop, held):
        self.loop, self.held, self.pending = loop, held, None

    def press(self, device, code):
        self.other()
        self.pending = (device, code, time.monotonic(), self.loop.call_later(CHORD_SECONDS, self.fire))

    def fire(self):
        device, code, pressed, _ = self.pending
        self.pending = None
        self.held(device, code, pressed)

    def other(self):
        """Another key went down, or Rook stops: a wait that runs ends with no talk."""
        if self.pending:
            self.pending[3].cancel()
            self.pending = None

    def release(self, device, code):
        """Whether this release ends a wait that runs: the key was tapped alone."""
        if self.pending and self.pending[:2] == (device, code):
            self.other()
            return True
        return False
