        cli = next(r for r in rows.values() if r["key"].startswith("cli-"))
        assert cli["outcome"] == "failed"
        c.journal.write("UPDATE sends SET outcome = NULL, settled = NULL WHERE key = ?", (cli["key"],))
        t3_shows()
        c = await restart(c)
        text = await report(c)
        assert "A second send would be a second message." in text and "safe to send" not in text, text
        for refused, why in ((cli["key"], "a second send would be a second message"), (key, "no brief")):
            with contextlib.suppress(SystemExit), contextlib.redirect_stdout(io.StringIO()) as out:
                relay.handoff_command(["--again", refused])
